*{box-sizing:border-box;margin:0;padding:0}
:root{--bg:#EFE7D6;--panel:#FBF6EB;--ink:#271D12;--ink2:#7D6C54;--line:#DFD2B6;--acc:#B4531F;--bad:#A93B2A}
body{font-family:Vazirmatn,'Segoe UI',sans-serif;background:var(--bg);color:var(--ink);line-height:1.8;min-height:100dvh;display:flex;align-items:center;justify-content:center;padding:20px}
.wrap{width:100%;max-width:400px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:20px;padding:28px 24px;box-shadow:0 18px 44px -18px rgba(56,38,18,.28)}
.logo{font-weight:900;font-size:18px;color:var(--acc);margin-bottom:14px}
h1{font-size:19px;margin-bottom:6px}
.sub{color:var(--ink2);font-size:13px;margin-bottom:16px;line-height:2}
label{display:block;font-size:12.5px;font-weight:700;color:var(--ink2);margin-bottom:12px}
label small{color:#AC9C81;font-weight:600}
input{width:100%;border:1px solid #CBBB99;background:#FFFDF8;border-radius:11px;padding:10px 13px;font:inherit;margin-top:4px;outline:0}
input:focus{border-color:var(--acc);box-shadow:0 0 0 3px rgba(180,83,31,.15)}
button{width:100%;border:1px solid var(--ink);background:var(--ink);color:#FBF6EB;font:inherit;font-weight:800;padding:11px;border-radius:12px;cursor:pointer;margin-top:4px}
button:hover{opacity:.92}
.err{background:rgba(169,59,42,.1);color:var(--bad);font-size:13px;font-weight:700;border-radius:10px;padding:9px 13px;margin-bottom:12px}
.hint{font-size:11px;color:#AC9C81;margin-top:12px;text-align:center}
.foot{font-size:10.5px;color:#AC9C81;text-align:center;margin-top:18px;border-top:1px dashed var(--line);padding-top:12px}
.ok{background:rgba(79,122,61,.1);color:#4F7A3D;font-size:13px;font-weight:700;border-radius:10px;padding:9px 13px;margin-bottom:12px}
.sec{border-top:1px dashed var(--line);margin-top:20px;padding-top:16px}
.sec h2{font-size:14px;margin-bottom:10px}
.row{display:flex;justify-content:space-between;font-size:13px;color:var(--ink2);padding:5px 0}
.row b{color:var(--ink)}
.btn2{display:inline-block;width:auto;padding:8px 16px;font-size:12.5px;border-radius:10px;text-decoration:none;text-align:center}
.red{background:var(--bad);border-color:var(--bad);margin-top:14px}
.warn{font-size:11.5px;color:#B07C1F;background:rgba(176,124,31,.1);border-radius:10px;padding:8px 12px;margin-bottom:12px}
/* ── داشبورد ادمین پلتفرم ── */
.wrap.wide{max-width:720px}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}
.st{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:10px;text-align:center}
.st b{display:block;font-size:20px;font-weight:900;color:var(--acc)}
.st span{font-size:11px;color:var(--ink2)}
.tools{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:6px}
.tools .btn2{width:auto}
.sec{border-top:1px dashed var(--line);margin-top:18px;padding-top:14px}
.sec h2{font-size:14.5px;margin-bottom:10px}
.ten{border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-bottom:10px;background:#FFFDF8}
.ten-h{display:flex;justify-content:space-between;align-items:center;gap:8px}
.ten-h b{font-size:14px}
.ten-meta{display:flex;gap:14px;flex-wrap:wrap;font-size:11.5px;color:var(--ink2);margin:6px 0}
.ten-meta a{color:var(--acc);text-decoration:none;font-weight:700}
.ten-ops{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.ten-ops .btn2{padding:5px 10px;font-size:11.5px;border-radius:8px;width:auto}
.btn2.red{background:var(--bad);border-color:var(--bad)}
.inline{display:inline-flex;gap:5px;align-items:center}
.pill{font-size:10px;font-weight:800;padding:2px 9px;border-radius:99px}
.pill.ok{background:rgba(79,122,61,.13);color:#4F7A3D}
.pill.bad{background:rgba(169,59,42,.12);color:var(--bad)}
.pill.warn{background:rgba(176,124,31,.14);color:#B07C1F}
.tmp{background:rgba(79,122,61,.1);color:#4F7A3D;border-radius:10px;padding:10px 13px;font-size:13px;margin-bottom:12px}
.tmp b{font-size:15px;letter-spacing:1px}
.tmp small{display:block;color:var(--ink2);font-weight:600}
.mini{font-size:11px;color:var(--ink3)}
input[type=number]{padding:5px;border:1px solid #CBBB99;border-radius:8px;font:inherit}

/* ── v5.0.5-test.4: کنترل کامل — داشبورد، فیلتر، جزئیات ── */
.stats{grid-template-columns:repeat(auto-fit,minmax(86px,1fr))}
.st.hot b{color:var(--bad)}
.fwrap{margin:4px 0 10px}
.fwrap input[type=text]{width:100%;padding:9px 13px;border:1px solid #CBBB99;background:#FFFDF8;border-radius:11px;font:inherit;font-size:13px;margin:0}
.chips{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}
.chip{width:auto;margin:0;padding:5px 13px;font-size:11.5px;font-weight:800;border-radius:99px;border:1px solid #CBBB99;background:#FFFDF8;color:var(--ink2);cursor:pointer}
.chip.on{background:var(--ink);border-color:var(--ink);color:#FBF6EB}
.dgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:4px 16px;font-size:11.5px;color:var(--ink2);padding:8px 4px 2px}
.dgrid b{color:var(--ink)}

*{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#EFE7D6;--panel:#FBF6EB;--panel2:#F2EADA;
  --ink:#271D12;--ink2:#7D6C54;--ink3:#AC9C81;
  --line:#DFD2B6;--line2:#CBBB99;
  --acc:#B4531F;--ok:#4F7A3D;--bad:#A93B2A;
  --sh:0 18px 44px -18px rgba(56,38,18,.28);
}
html{scroll-behavior:smooth}
body{font-family:Vazirmatn,'Segoe UI',sans-serif;background:var(--bg);color:var(--ink);line-height:1.9;font-size:15px}

/* ── هدر ── */
.hd{position:sticky;top:0;z-index:50;background:rgba(239,231,214,.85);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.hd-in{max-width:1020px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:12px 20px}
.brand{font-weight:900;font-size:18px;color:var(--acc)}
.hd-btn{text-decoration:none;color:var(--ink);font-size:13px;font-weight:800;border:1px solid var(--line2);border-radius:99px;padding:7px 16px;transition:.15s}
.hd-btn:hover{background:var(--panel2)}

/* ── هیرو ── */
.hero{max-width:1020px;margin:0 auto;display:grid;grid-template-columns:1.2fr .8fr;align-items:center;gap:30px;padding:60px 20px 40px}
.kick{color:var(--acc);font-weight:800;font-size:13px}
h1{font-size:clamp(28px,4.5vw,44px);font-weight:900;line-height:1.6;margin:10px 0 14px}
h1 b{color:var(--acc)}
.lead{color:var(--ink2);font-size:15px;max-width:50ch}
.cta{display:inline-block;margin-top:22px;background:var(--ink);color:#FBF6EB;text-decoration:none;font-weight:800;padding:13px 30px;border-radius:14px;box-shadow:var(--sh);transition:.15s}
.cta:hover{transform:translateY(-2px)}
/* ماکاپ موبایل — فقط با CSS */
.hero-art{display:flex;justify-content:center}
.mock{width:210px;background:#fff;border:1px solid var(--line2);border-radius:28px;padding:16px 14px;box-shadow:var(--sh);transform:rotate(-3deg)}
.mock-head{height:56px;border-radius:14px;background:linear-gradient(135deg,#B4531F,#D96C3A);margin-bottom:12px}
.mock-line{height:9px;border-radius:99px;background:var(--panel2);margin:9px 0}
.w80{width:80%}.w60{width:60%}.w70{width:70%}
.mock-row{display:flex;gap:7px;margin:10px 0}
.mock-row i{flex:1;height:34px;border-radius:9px;background:var(--panel2)}
.mock-row i:first-child{background:#EFD9C4}
.mock-btn{height:38px;border-radius:12px;background:var(--acc);margin-top:14px}

/* ── ویژگی‌ها ── */
.feats{max-width:1020px;margin:0 auto;display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;padding:20px 20px 40px}
.feat{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:18px}
.fi{font-size:26px;margin-bottom:6px}
.feat h3{font-size:14.5px;font-weight:800;margin-bottom:4px}
.feat p{font-size:12.5px;color:var(--ink2);line-height:2}

/* ── ثبت‌نام ── */
.reg{max-width:520px;margin:0 auto;padding:20px 20px 50px}
.reg-card{background:var(--panel);border:1px solid var(--line);border-radius:20px;padding:28px 24px;box-shadow:var(--sh)}
.reg-card h2{font-size:20px;margin-bottom:4px}
.reg-sub{color:var(--ink2);font-size:13px;margin-bottom:18px}
label{display:block;font-size:12.5px;font-weight:700;color:var(--ink2);margin-bottom:14px}
input[type=text],input[type=tel],input[type=password]{width:100%;border:1px solid var(--line2);background:#FFFDF8;border-radius:11px;padding:10px 13px;font:inherit;margin-top:4px;outline:0;transition:.15s}
input:focus{border-color:var(--acc);box-shadow:0 0 0 3px rgba(180,83,31,.15)}
.slug{display:inline-block;font-size:11px;font-weight:800;direction:ltr;unicode-bidi:plaintext;color:var(--ink3)}
.slug.ok{color:var(--ok)}
.slug.bad{color:var(--bad)}
.hint{font-size:11px;color:var(--ink3);margin:-8px 0 12px}
/* چک‌لیست زندهٔ رمز عبور */
.pw-checks{display:flex;flex-wrap:wrap;gap:6px 16px;margin:-8px 0 10px;padding:9px 13px;background:#FFFDF8;border:1px dashed var(--line2);border-radius:11px}
.pw-checks span{font-size:11.5px;font-weight:700;color:var(--ink3);transition:.15s}
.pw-checks span.ok{color:var(--ok)}
.pw-checks span.no{color:var(--bad)}
.pw-warn{font-size:11.5px;font-weight:700;color:var(--bad);background:rgba(169,59,42,.07);border:1px solid rgba(169,59,42,.25);border-radius:10px;padding:8px 12px;margin:-4px 0 12px;line-height:1.9}
.chk{display:flex;gap:9px;align-items:flex-start;font-size:11.5px;font-weight:600;color:var(--ink2);line-height:1.9}
.chk input{width:17px;height:17px;margin-top:5px;accent-color:var(--acc);flex:none}
.msg{min-height:20px;font-size:13px;font-weight:700;margin:4px 0}
.msg.ok{color:var(--ok)}
.msg.bad{color:var(--bad)}
.msg.warn{color:#8A5A17}
input.bad-in{border-color:var(--bad)!important;background:#FDF6F3}
button{width:100%;border:1px solid var(--ink);background:var(--ink);color:#FBF6EB;font:inherit;font-weight:800;font-size:15px;padding:13px;border-radius:13px;cursor:pointer;transition:.15s}
button:disabled{opacity:.45;cursor:not-allowed}
button:not(:disabled):hover{transform:translateY(-1px)}
.foot{font-size:12px;color:var(--ink2);text-align:center;margin-top:18px;border-top:1px dashed var(--line);padding-top:14px}
.foot a{color:var(--acc);font-weight:800;text-decoration:none}

/* ── فوتر ── */
.ft{text-align:center;padding:26px 20px 40px;border-top:1px solid var(--line);font-size:12.5px}
.ft b{color:var(--acc)}
.muted{color:var(--ink3);font-size:11px;margin-top:4px}

@media(max-width:760px){
 .hero{grid-template-columns:1fr;padding:36px 20px 20px;text-align:center}
 .lead{margin:0 auto}
 .hero-art{order:2}
}

/* ════════════════════════════════════════════════════════════
   سِرو — استایل کامل
   ════════════════════════════════════════════════════════════ */
*{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#EFE7D6; --panel:#FBF6EB; --panel2:#F2EADA;
  --ink:#271D12; --ink2:#7D6C54; --ink3:#AC9C81;
  --line:#DFD2B6; --line2:#CBBB99;
  --accent:#B4531F; --ok:#4F7A3D; --bad:#A93B2A; --warn:#B07C1F;
  --sh:0 18px 44px -18px rgba(56,38,18,.28);
}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{font-family:Vazirmatn,'Segoe UI',sans-serif;background:var(--bg);color:var(--ink);line-height:1.7;font-size:15px;min-height:100dvh}
body::after{content:'';position:fixed;inset:0;pointer-events:none;z-index:999;opacity:.05;mix-blend-mode:multiply;
 background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>")}
body.locked{overflow:hidden}
button{font-family:inherit}
.ic{flex:none;display:block}
small{font-size:.78em}
#errbox{display:none;position:fixed;top:0;left:0;right:0;z-index:99999;background:#A93B2A;color:#fff;font:13px/1.9 Vazirmatn,Tahoma,sans-serif;padding:10px 14px;direction:rtl;text-align:right}
#errbox b{font-weight:800}
#errbox .err-tech{color:#fff}

.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid var(--ink);background:var(--ink);color:#FBF6EB;font:inherit;font-weight:700;font-size:14px;padding:10px 18px;border-radius:12px;cursor:pointer;transition:.18s}
.btn:hover{transform:translateY(-1px)}
.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line2)}
.btn.blk{width:100%}
.btn.sm{padding:7px 12px;font-size:12.5px;border-radius:10px}
.btn.danger{background:var(--bad);border-color:var(--bad)}
.btn:disabled{opacity:.5;pointer-events:none}
.icobtn{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:10px;border:1px solid transparent;background:transparent;color:var(--ink2);cursor:pointer;transition:.15s}
.icobtn:hover{background:var(--panel2);color:var(--ink);border-color:var(--line)}
.icobtn.xs{width:24px;height:24px;border-radius:7px}
.icobtn.danger:hover{color:var(--bad)}
label.f{display:block;margin-bottom:12px}
label.f span{display:block;font-size:12px;font-weight:700;color:var(--ink2);margin-bottom:5px}
label.f input,label.f select{width:100%}
input,select,textarea{border:1px solid var(--line2);background:#FFFDF8;border-radius:11px;padding:10px 13px;font:inherit;color:var(--ink);outline:0;transition:.15s}
input:focus,select:focus,textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 16%,transparent)}
.seg{display:inline-flex;background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:3px;gap:3px}
.seg button{border:0;background:transparent;font:inherit;font-size:12.5px;font-weight:700;padding:6px 13px;border-radius:9px;color:var(--ink2);cursor:pointer;display:inline-flex;gap:6px;align-items:center;transition:.15s}
.seg button.on{background:var(--ink);color:var(--panel)}
.pill{font-size:10.5px;font-weight:800;padding:3px 10px;border-radius:99px;background:var(--panel2);color:var(--ink2);white-space:nowrap}
.pill.warn{background:color-mix(in srgb,var(--warn) 14%,var(--panel));color:var(--warn)}
.pill.info{background:color-mix(in srgb,var(--accent) 12%,var(--panel));color:var(--accent)}
.pill.ok{background:color-mix(in srgb,var(--ok) 13%,var(--panel));color:var(--ok)}
.spin{width:15px;height:15px;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;border-radius:99px;display:inline-block;animation:rot .7s linear infinite}
@keyframes rot{to{transform:rotate(360deg)}}
.m-acts{display:flex;gap:10px;margin-top:16px}
.m-acts .btn{flex:1}
.dim{color:var(--ink3);font-size:12px}
.err{color:var(--bad);font-size:12.5px;font-weight:700;margin-top:8px}

#toasts{position:fixed;bottom:18px;right:50%;transform:translateX(50%);z-index:1400;display:flex;flex-direction:column;gap:8px;align-items:center;width:min(92vw,430px)}
.toast{display:flex;align-items:center;gap:10px;background:var(--ink);color:var(--panel);padding:11px 16px;border-radius:12px;font-size:13.5px;box-shadow:var(--sh);opacity:0;transform:translateY(12px);transition:.28s;width:100%}
.toast.in{opacity:1;transform:none}
.t-act{background:transparent;border:1px solid rgba(255,255,255,.35);color:#fff;border-radius:8px;padding:3px 12px;font:inherit;font-size:12px;cursor:pointer;margin-inline-start:auto;flex:none}

#modal-root{position:fixed;inset:0;z-index:1200;display:none}
#modal-root.open{display:block}
.ovl{position:absolute;inset:0;background:rgba(30,20,10,.45);animation:fIn .2s}
@keyframes fIn{from{opacity:0}}
.sheet{position:absolute;left:50%;transform:translateX(-50%);bottom:0;width:min(100vw,560px);max-height:90dvh;background:var(--panel);border-radius:22px 22px 0 0;box-shadow:var(--sh);display:flex;flex-direction:column;animation:shUp .3s cubic-bezier(.2,.9,.3,1)}
@keyframes shUp{from{transform:translate(-50%,46px);opacity:.5}}
.sh-head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--line);flex:none}
.sh-head h3{font-size:15px}
.sh-body{padding:16px 18px 24px;overflow:auto}

.home{max-width:1020px;margin:0 auto;padding:22px 22px 60px}
.home-top{display:flex;justify-content:space-between;align-items:center;gap:10px}
.brandmark{display:flex;align-items:center;gap:9px;font-size:17px;font-weight:800}
.brandmark .ic{color:var(--accent)}
.ver{font-size:10.5px;font-weight:700;color:var(--ink2);border:1px solid var(--line2);padding:2px 9px;border-radius:99px}
.hero{display:grid;grid-template-columns:1.25fr .75fr;align-items:center;gap:26px;padding:50px 0 26px}
.kicker{font-size:12.5px;font-weight:800;color:var(--accent)}
.hero h1{font-size:clamp(29px,4.6vw,46px);font-weight:900;line-height:1.5;margin:10px 0 12px}
.lead{color:var(--ink2);max-width:54ch;font-size:14.5px}
.cupart{width:min(225px,58vw);margin:0 auto;display:block}
.cup-line{fill:none;stroke:var(--ink);stroke-width:4;stroke-linecap:round;stroke-linejoin:round}
.steam{fill:none;stroke:var(--ink3);stroke-width:3.4;stroke-linecap:round;stroke-dasharray:22 95;animation:stm 3.6s linear infinite}
.st2{animation-delay:1.2s}.st3{animation-delay:2.4s}
@keyframes stm{0%{stroke-dashoffset:117;opacity:0}30%{opacity:.9}65%{opacity:.45}100%{stroke-dashoffset:-90;opacity:0}}
.roles{border-top:1px solid var(--line2)}
.role-row{display:flex;align-items:center;gap:16px;width:100%;text-align:start;background:transparent;border:0;border-bottom:1px solid var(--line);padding:19px 6px;cursor:pointer;font:inherit;transition:.18s;color:var(--ink)}
.role-row:hover{background:var(--panel);padding-inline-start:16px}
.rr-no{font-size:11px;font-weight:800;color:var(--ink3);font-feature-settings:'tnum'}
.rr-ic{width:42px;height:42px;border:1px solid var(--line2);border-radius:12px;display:flex;align-items:center;justify-content:center;flex:none}
.rr-tx{flex:1;display:flex;flex-direction:column}
.rr-tx b{font-size:17px;font-weight:800}
.rr-tx small{color:var(--ink2);font-size:12.5px}
.rr-ar{color:var(--ink3);transition:.18s}
.role-row:hover .rr-ar{color:var(--accent);transform:translateX(-5px)}
.home-foot{margin-top:26px;color:var(--ink3);font-size:11.5px;text-align:center;line-height:2}

.loginwrap{min-height:100dvh;display:flex;align-items:center;justify-content:center;padding:20px}
.login-card{width:min(94vw,380px);background:var(--panel);border:1px solid var(--line);border-radius:20px;padding:26px 22px;box-shadow:var(--sh)}
.login-card .ic{color:var(--accent)}
.login-card h2{font-size:20px;margin:8px 0 4px}
.login-card>p{color:var(--ink2);font-size:12.5px;margin-bottom:18px;line-height:2}
.lk-row{display:flex;justify-content:space-between;align-items:center;margin:4px 0 14px}
.linkbtn{border:0;background:transparent;color:var(--accent);font:inherit;font-size:12px;font-weight:800;cursor:pointer;padding:2px}
.linkbtn:hover{text-decoration:underline}

.appbar{position:sticky;top:0;z-index:60;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 16px;background:color-mix(in srgb,var(--bg) 82%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.ab-l{display:flex;align-items:center;gap:10px;min-width:0}
.ab-l b{font-size:14.5px;display:block;line-height:1.25}
.ab-l small{color:var(--ink2);font-size:11px}
.ab-r{display:flex;align-items:center;gap:10px}
.atabs{display:flex;gap:4px;background:var(--panel2);border:1px solid var(--line);padding:3px;border-radius:12px;flex-wrap:wrap}
.atab{display:inline-flex;align-items:center;gap:7px;border:0;background:transparent;font:inherit;font-size:13px;font-weight:700;color:var(--ink2);padding:7px 14px;border-radius:9px;cursor:pointer;transition:.15s}
.atab.on{background:var(--ink);color:var(--panel)}
.save-badge{font-size:10.5px;color:var(--ink3);font-weight:700;transition:.2s;white-space:nowrap}
.save-badge.flash{color:var(--ok)}

.wiz{max-width:1000px;margin:0 auto;padding:18px 18px 50px}
.wiz-top{display:flex;align-items:center;gap:10px;margin-bottom:6px}
.wiz-top b{font-size:17px;font-weight:900}
.wiz-top .dim{margin-inline-start:auto}
.wiz-steps{display:flex;gap:5px;flex-wrap:wrap;margin:12px 0 20px}
.wstep{font-size:10px;font-weight:800;padding:4px 10px;border-radius:99px;background:var(--panel);border:1px solid var(--line);color:var(--ink3)}
.wstep.on{background:var(--ink);color:var(--panel);border-color:var(--ink)}
.wstep.done{color:var(--ok);border-color:color-mix(in srgb,var(--ok) 45%,var(--line))}
.wiz-grid{display:grid;grid-template-columns:1fr 335px;gap:22px;align-items:start}
.wiz-card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:22px}
.wiz-card h2{font-size:18px;font-weight:900;margin-bottom:4px}
.wiz-card>p{color:var(--ink2);font-size:13px;margin-bottom:16px;line-height:2}
.wiz-nav{display:flex;gap:10px;margin-top:20px}
.wiz-nav .btn{flex:1}
.wiz-prev-phone .phone{height:min(560px,72dvh)}
.wiz-hint{font-size:11.5px;color:var(--ink3);line-height:2;margin-top:10px}

.designer{display:grid;grid-template-columns:312px 1fr;max-width:1180px;margin:0 auto;align-items:start}
.d-tools{border-inline-end:1px solid var(--line);padding:14px 12px 50px;position:sticky;top:56px;max-height:calc(100dvh - 56px);overflow:auto}
.tool-g{margin-bottom:8px;border:1px solid var(--line);border-radius:14px;background:var(--panel);overflow:hidden}
.tool-g>h4{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:800;color:var(--ink2);padding:8px 12px;background:var(--panel2);cursor:pointer;user-select:none;-webkit-user-select:none;transition:.15s}
.tool-g>h4:hover{color:var(--ink)}
.tplus{margin-inline-start:auto;color:var(--ink3);transition:transform .22s;display:flex;flex:none}
.tool-g.open .tplus{transform:rotate(45deg);color:var(--accent)}
.tg-b{display:none;padding:9px 12px 12px}
.tool-g.open .tg-b{display:block}
.tool-g .tg-b>p{font-size:11.5px;color:var(--ink2);line-height:1.9;margin-bottom:8px}
.tool-g .tg-b label.f{margin-bottom:8px}
.tool-g .tg-b label.f span{font-size:11px;margin-bottom:3px}
.tool-g .tg-b input,.tool-g .tg-b select{padding:8px 10px;font-size:12.5px}
.tool-g .btn.sm{padding:6px 10px;font-size:11.5px}
.tool-g .row-btns{gap:6px}
.tool-g .tg-b .mini{font-size:10.5px;line-height:1.8}
/* v5.0.4-test.2: دکمهٔ همیشه‌نمایان «بارگذاری منو از اکسل» — بالای ستون راست */
.excel-cta{display:flex;align-items:center;gap:9px;width:100%;text-align:start;padding:10px 11px;margin-bottom:10px;border:1.5px solid color-mix(in srgb,var(--accent) 45%,var(--line));border-radius:14px;background:color-mix(in srgb,var(--accent) 9%,var(--panel));color:var(--ink);cursor:pointer;font-family:inherit;transition:.15s}
.excel-cta:hover{background:color-mix(in srgb,var(--accent) 16%,var(--panel));border-color:var(--accent)}
.excel-cta .xc-ic{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:var(--accent);color:#fff;flex:none}
.excel-cta .xc-tx{display:flex;flex-direction:column;align-items:flex-start;gap:1px;min-width:0;flex:1;text-align:start}
.excel-cta .xc-tx b{font-size:12.5px;font-weight:800}
.excel-cta .xc-tx small{font-size:10.5px;color:var(--ink2)}
.excel-cta .xc-ch{color:var(--accent);flex:none;display:grid;place-items:center}
.tool-g.flash{border-color:var(--accent);animation:tgflash 1.6s ease}
@keyframes tgflash{0%,55%{box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 30%,transparent)}100%{box-shadow:0 0 0 0 transparent}}
/* v5.0.5: هشدار امنیت رمزها در تنظیمات */
.pwl{display:flex;align-items:flex-start;gap:8px;padding:8px 10px;border-radius:10px;font-size:12px;line-height:1.9;margin-bottom:6px}
.pwl b{font-weight:800}
.pwl svg{flex:none;margin-top:4px}
.pwl.ok{background:color-mix(in srgb,var(--ok) 12%,var(--panel));color:var(--ok)}
.pwl.bad{background:color-mix(in srgb,var(--warn) 14%,var(--panel));color:var(--warn)}
.row-btns{display:flex;gap:8px}
.row-btns .btn{flex:1}
.d-canvas{padding:16px 20px 70px;background:var(--panel2);min-height:calc(100dvh - 56px)}
.d-canvas-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:0 auto 14px;max-width:460px}
.d-canvas-head>span{font-size:11.5px;font-weight:800;color:var(--ink3)}
.phone{max-width:440px;margin:0 auto;height:min(780px,calc(100dvh - 155px));border-radius:30px;border:1px solid var(--line2);box-shadow:var(--sh);overflow:hidden;background:#fff}
.phone-inner{height:100%;overflow-y:auto;overscroll-behavior:contain}

.ven-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.ven-btn{display:flex;align-items:center;gap:8px;border:1px solid var(--line2);background:transparent;border-radius:11px;padding:8px 10px;font:inherit;font-size:12px;font-weight:700;color:var(--ink2);cursor:pointer;transition:.15s}
.ven-btn.on{border-color:var(--ink);color:var(--ink);background:var(--panel)}
.ven-btn .ic{color:var(--ink3)}
.ven-btn.on .ic{color:var(--accent)}
.logo-box{display:flex;align-items:center;gap:10px}
.logo-prev{width:44px;height:44px;border-radius:14px;border:1.5px dashed var(--line2);display:flex;align-items:center;justify-content:center;color:var(--ink3);overflow:hidden;flex:none;background:repeating-conic-gradient(#E7DDC6 0 25%,#FBF6EB 0 50%) 0 0/12px 12px}
.logo-prev img{width:100%;height:100%;object-fit:contain}
.pal-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:10px}
.pal{border:1.5px solid var(--line);border-radius:12px;padding:6px;background:var(--panel);cursor:pointer;transition:.15s;width:100%}
.pal:hover{border-color:var(--line2)}
.pal.on{border-color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}
.pal-strip{display:flex;gap:3px;margin-bottom:4px}
.pal-strip i{flex:1;height:12px;border-radius:4px}
.pal b{font-size:10.5px;font-weight:800;color:var(--ink2);display:flex;justify-content:space-between;align-items:center;gap:4px}
.paldel{width:20px;height:20px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;color:var(--ink3)}
.paldel:hover{color:var(--bad);background:var(--panel2)}
.cp-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin:8px 0}
.cp{display:flex;flex-direction:column;align-items:center;gap:2px;font-size:8.5px;color:var(--ink3);font-weight:700}
.cp input{width:100%;height:26px;padding:2px;border:1px solid var(--line2);border-radius:8px;background:var(--panel);cursor:pointer}
.grad-row{display:flex;gap:6px;margin-top:8px}
.grad-row .cp{flex:1}
.sched-edit{display:flex;flex-direction:column;gap:4px}
.sc-day{display:flex;align-items:center;gap:5px;border:1px solid var(--line);border-radius:9px;padding:3px 7px;background:var(--panel2)}
.sc-day.x{opacity:.6}
.sc-top{display:flex;align-items:center;gap:4px;flex:none;width:88px}
.sc-top b{flex:1;font-size:10.5px;font-weight:800;color:var(--ink2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sc-x{font-size:9.5px;border:1px solid var(--line2);border-radius:7px;padding:1px 7px;background:transparent;color:var(--ink3);cursor:pointer;white-space:nowrap;flex:none}
.sc-x.on{color:var(--bad);border-color:var(--bad);font-weight:800}
.sc-times{display:flex;align-items:center;gap:3px;flex:1;min-width:0}
.sc-times input[type=time]{flex:1;min-width:0;padding:2px 1px;font-size:10.5px;border-radius:6px;border:1px solid var(--line2);background:#FFFDF8;font-family:inherit;text-align:center;direction:ltr}

.mframe{--m-bg:var(--panel);--m-ink:var(--ink);--m-sub:var(--ink2);--m-line:var(--line);--m-line2:var(--line);--acc:var(--accent);background:var(--m-bg);color:var(--m-ink);min-height:100%;padding-bottom:34px;position:relative}
.mbg{position:absolute;inset:0;z-index:0;overflow:hidden}
.mbg img,.mbg video{width:100%;height:100%;object-fit:cover}
.mbg-ov{position:absolute;inset:0}
.mn-cont{position:relative;z-index:1}
.mn-head{padding:30px 22px 12px;text-align:center}
.mn-head.hbg{position:relative;margin:14px 14px 0;padding:46px 22px 26px;border-radius:20px;overflow:hidden;background-size:cover;background-position:center}
.mn-head.hbg .hbov2{position:absolute;inset:0;background:linear-gradient(180deg,rgba(20,12,6,.5),rgba(20,12,6,.3))}
.mn-head.hbg>*:not(.hbov2){position:relative;z-index:1}
.mn-head.hbg .mn-logo{background:rgba(255,251,242,.94);padding:4px;box-shadow:0 4px 14px rgba(0,0,0,.25)}
.mn-head.hbg .mn-name{color:#FFF8EC;text-shadow:0 1px 8px rgba(0,0,0,.35)}
.mn-head.hbg .mn-tag{color:#FFE3C2;text-shadow:0 1px 6px rgba(0,0,0,.3)}
.mn-head.hbg .mn-meta{color:rgba(255,248,236,.88)}
.mn-head.hbg .mn-rule i{background:rgba(255,248,236,.5)}
.mn-head.hbg .mn-rule b{background:#FFF8EC}
.mn-logo{width:54px;height:54px;object-fit:contain;border-radius:14px;margin-bottom:2px}
.mn-ic{color:var(--acc);margin-bottom:4px}
.mn-name{font-size:30px;font-weight:900;line-height:1.35;outline:none}
.mn-tag{color:var(--acc);font-weight:700;font-size:14px;margin-top:2px;outline:none}
.mn-meta{display:flex;gap:8px;justify-content:center;color:var(--m-sub);font-size:11.5px;margin-top:10px;flex-wrap:wrap;outline:none}
.mn-rule{display:flex;align-items:center;gap:10px;justify-content:center;margin-top:16px}
.mn-rule i{width:52px;height:1px;background:var(--m-line2)}
.mn-rule b{width:7px;height:7px;background:var(--acc);transform:rotate(45deg)}
.sched-chip{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:800;padding:4px 13px;border-radius:99px;border:1px solid var(--m-line2);margin-top:10px}
.sched-chip .dot{width:8px;height:8px}
.sched-chip.open .dot{background:#4F7A3D;animation:pu 1.6s infinite}
.sched-chip.closed .dot{background:#A93B2A}
.sched-d{margin-top:8px;font-size:11.5px;color:var(--m-sub)}
.sched-d summary{cursor:pointer;font-weight:800;display:inline-flex;gap:5px;align-items:center;list-style:none}
.sched-row{display:flex;justify-content:space-between;gap:12px;padding:3px 0;border-bottom:1px dashed var(--m-line)}
.sched-row.today{color:var(--acc);font-weight:800}

.mn-tabs{position:sticky;top:0;z-index:5;margin-top:14px;padding:8px 12px;background:color-mix(in srgb,var(--m-bg) 78%,transparent);backdrop-filter:blur(12px);border-bottom:1px solid var(--m-line)}
.mn-tabs-in{display:flex;overflow-x:auto;scrollbar-width:none;gap:6px;padding:0 4px}
.mn-tabs-in::-webkit-scrollbar{display:none}
.mnt{flex:none;border:1px solid var(--m-line2);background:color-mix(in srgb,var(--m-bg) 55%,transparent);font:inherit;font-size:12.5px;font-weight:800;color:var(--m-sub);padding:6px 15px;border-radius:99px;cursor:pointer;transition:.15s}
.mnt.on{background:var(--acc);border-color:var(--acc);color:#FFF8EC}
.mnt.add{border-style:dashed;color:var(--acc);background:transparent;padding:6px 11px}
.mn-tools{padding:12px 22px 0;display:flex;flex-direction:column;gap:8px}
.mn-search{display:flex;align-items:center;gap:8px;border:1px solid var(--m-line2);border-radius:12px;padding:9px 12px;background:color-mix(in srgb,var(--m-bg) 60%,transparent);color:var(--m-sub)}
.mn-search input{flex:1;border:0;outline:0;background:transparent;font:inherit;color:var(--m-ink);padding:0;box-shadow:none;border-radius:0}
.mn-fchips{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none}
.mnf{flex:none;display:inline-flex;align-items:center;gap:4px;font:inherit;font-size:11px;font-weight:800;padding:5px 12px;border-radius:99px;border:1px solid var(--m-line2);background:transparent;color:var(--m-sub);cursor:pointer;transition:.15s}
.mnf.on{background:var(--acc);border-color:var(--acc);color:#FFF8EC}
.bnr-zone{padding:14px 22px 0}
.bnrs{display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}
.bnr-w{flex:0 0 82%;scroll-snap-align:center;min-width:0}
.bnr{position:relative;min-height:88px;border-radius:16px;background:var(--acc);color:#FFF8EC;padding:15px 17px;display:flex;flex-direction:column;justify-content:center;overflow:hidden;background-size:cover;background-position:center}
.bnr b{font-size:15.5px;font-weight:900;outline:none}
.bnr span{font-size:11.5px;opacity:.88;outline:none}
.bnr-empty{flex:0 0 46%;min-height:88px;border:1.5px dashed var(--m-line2);border-radius:16px;display:flex;align-items:center;justify-content:center}
.chipbtn{display:inline-flex;align-items:center;gap:5px;font:inherit;font-size:11px;font-weight:800;padding:5px 10px;border-radius:9px;border:1px solid var(--m-line2);background:transparent;color:var(--m-sub);cursor:pointer;transition:.15s}
.mn-cat{padding:20px 22px 4px;scroll-margin-top:60px}
.mn-cat-h{display:flex;align-items:center;gap:8px;margin-bottom:12px}
.mn-cat-h h2{font-size:15px;font-weight:900;outline:none;display:inline-flex;align-items:center;gap:8px}
.mn-cat-h h2::before{content:'';width:8px;height:8px;background:var(--acc);transform:rotate(45deg);flex:none;border-radius:2px}
.mn-n{font-size:10.5px;font-weight:700;color:var(--acc);border:1px solid var(--acc);border-radius:99px;min-width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center;padding:0 5px;font-feature-settings:'tnum'}
.mn-items{display:flex;flex-direction:column;gap:15px}
.mn-items.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.mn-line{display:flex;align-items:baseline;gap:8px}
.mn-iname{font-size:15.5px;font-weight:700;outline:none;min-width:12px}
.mn-lead{flex:1;border-bottom:2px dotted var(--m-line2);transform:translateY(-4px);min-width:12px}
.mn-price{font-weight:800;color:var(--acc);white-space:nowrap;font-feature-settings:'tnum';outline:none;font-size:14.5px}
.mn-price small{font-size:9.5px;font-weight:600;color:var(--m-sub);margin-inline-start:3px}
.mn-sub{display:flex;align-items:center;gap:10px;margin-top:3px}
.mn-idesc{font-size:12.5px;color:var(--m-sub);flex:1;outline:none}
.mgi{border:1px solid var(--m-line);border-radius:14px;overflow:hidden;background:var(--m-bg);display:flex;flex-direction:column}
.gimg{position:relative;aspect-ratio:16/10;background:var(--m-line);display:flex;align-items:center;justify-content:center;color:var(--m-sub)}
.gimg img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.mgi-b{padding:10px 12px 12px;display:flex;flex-direction:column;gap:3px;flex:1}
.mgi-b h3{font-size:14px;font-weight:700;outline:none}
.mgi-b p{font-size:11.5px;color:var(--m-sub);flex:1;outline:none}
.mgi-f{display:flex;align-items:center;justify-content:space-between;margin-top:6px;gap:8px}
.tagrow{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}
.tagchip{display:inline-flex;align-items:center;gap:4px;font:inherit;font-size:10.5px;font-weight:800;padding:4px 9px;border-radius:99px;border:1px solid var(--m-line2);background:transparent;color:var(--m-sub);cursor:pointer;transition:.15s}
.tagchip.on{border-color:var(--tc,var(--acc));color:var(--tc,var(--acc));background:color-mix(in srgb,var(--tc,var(--acc)) 12%,transparent)}
/* v5.0.1: دکمهٔ «تایید» کارت برچسب‌ها + حالت بازگشایی */
.tagchip.ok{border-color:#4F7A3D;color:#4F7A3D;background:color-mix(in srgb,#4F7A3D 12%,transparent)}
.tagchip.ok:active{transform:scale(.94)}
.tagchip.ghost{border-style:dashed}
.tchips{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}
.tchip{display:inline-flex;align-items:center;gap:4px;font-size:10px;font-weight:800;padding:3px 8px;border-radius:99px}
.tchip.tp{color:#A87412;background:color-mix(in srgb,#A87412 13%,transparent)}
.tchip.tc{color:#4F7A3D;background:color-mix(in srgb,#4F7A3D 13%,transparent)}
.tchip.td{color:#5B7085;background:color-mix(in srgb,#5B7085 14%,transparent)}
.tchip.to{color:#A93B2A;background:color-mix(in srgb,#A93B2A 13%,transparent)}
.tchip.ts{color:#837D70;background:color-mix(in srgb,#837D70 16%,transparent)}
.qslot{display:inline-flex}
.qbtn{width:29px;height:29px;border-radius:99px;border:0;background:var(--acc);color:#FFF6E9;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;transition:.15s}
.qstep{display:inline-flex;align-items:center;gap:2px;border:1.5px solid var(--acc);border-radius:99px;padding:2px}
.qstep button{width:24px;height:24px;border-radius:99px;border:0;background:transparent;color:var(--acc);display:inline-flex;align-items:center;justify-content:center;cursor:pointer}
.qstep b{min-width:20px;text-align:center;font-size:13px;color:var(--acc);font-feature-settings:'tnum'}
.iops{display:inline-flex;gap:2px;opacity:.55;transition:.15s;flex:none}
.mni:hover .iops,.mgi:hover .iops{opacity:1}
.additem{display:flex;align-items:center;gap:6px;border:1.5px dashed var(--m-line2);background:transparent;color:var(--m-sub);font:inherit;font-size:12.5px;font-weight:700;padding:9px;border-radius:10px;margin-top:14px;cursor:pointer;width:100%;justify-content:center;transition:.15s}
.mn-foot{text-align:center;color:var(--m-sub);font-size:11px;padding:26px 0 6px}
[data-ce]{cursor:text;border-radius:4px;transition:box-shadow .15s,background .15s;min-width:14px}
[data-ce]:hover{box-shadow:0 0 0 1.5px color-mix(in srgb,var(--acc) 40%,transparent)}
[data-ce]:focus{box-shadow:0 0 0 2px var(--acc);background:color-mix(in srgb,var(--acc) 10%,transparent);outline:none}

.cust-shell{max-width:520px;margin:0 auto;min-height:100dvh;padding-bottom:110px;position:relative}
.tabbar{position:fixed;bottom:0;left:0;right:0;display:flex;justify-content:center;z-index:70;pointer-events:none}
.tabbar .inner{pointer-events:auto;display:grid;grid-template-columns:repeat(4,1fr);width:100%;max-width:520px;background:color-mix(in srgb,var(--panel) 93%,transparent);backdrop-filter:blur(10px);border-top:1px solid var(--line)}
.tab{position:relative;display:flex;flex-direction:column;align-items:center;gap:3px;border:0;background:transparent;font:inherit;font-size:10.5px;font-weight:700;color:var(--ink3);padding:9px 0 calc(9px + env(safe-area-inset-bottom));cursor:pointer;transition:.15s}
.tab.on{color:var(--ink)}
.tab.on::after{content:'';position:absolute;top:-1px;width:26px;height:2.5px;background:var(--accent);border-radius:2px}
.tb-badge{position:absolute;top:4px;inset-inline-start:calc(50% + 7px);min-width:17px;height:17px;border-radius:99px;background:var(--accent);color:#FFF6E9;font-size:10px;font-style:normal;display:flex;align-items:center;justify-content:center;padding:0 4px;font-feature-settings:'tnum'}
.cartbar{position:fixed;bottom:calc(70px + env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);width:min(92vw,488px);display:flex;align-items:center;gap:10px;background:var(--ink);color:var(--panel);border:0;border-radius:16px;padding:12px 16px;font:inherit;font-size:14px;font-weight:700;cursor:pointer;box-shadow:var(--sh);z-index:65}
.cartbar b{margin-inline-start:auto;font-feature-settings:'tnum'}
.cb-badge{background:var(--accent);color:#fff;min-width:22px;height:22px;border-radius:99px;display:flex;align-items:center;justify-content:center;font-size:12px;font-feature-settings:'tnum'}

.cwrap{padding:16px 18px 40px}
.cwrap h2{font-size:19px;font-weight:800;margin-bottom:6px}
